    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Demonstrated instances: the selected component is recolored; all else stays fixed.
